bool Sexy::ExtractResourcesByName(ResourceManager* theManager, const char* theName)
{
	if (strcmp(theName, "Adventure") == 0)
		return ExtractAdventureResources(theManager);
	if (strcmp(theName, "Character") == 0)
		return ExtractCharacterResources(theManager);
	if (strcmp(theName, "Dialog") == 0)
		return ExtractDialogResources(theManager);
	if (strcmp(theName, "Game") == 0)
		return ExtractGameResources(theManager);
	if (strcmp(theName, "Help") == 0)
		return ExtractHelpResources(theManager);
	if (strcmp(theName, "IP") == 0)
		return ExtractIPResources(theManager);
	if (strcmp(theName, "Init") == 0)
		return ExtractInitResources(theManager);
	if (strcmp(theName, "Interface") == 0)
		return ExtractInterfaceResources(theManager);
	if (strcmp(theName, "LevelSelect") == 0)
		return ExtractLevelSelectResources(theManager);
	if (strcmp(theName, "Load") == 0)
		return ExtractLoadResources(theManager);
	if (strcmp(theName, "LoadingThread") == 0)
		return ExtractLoadingThreadResources(theManager);
	if (strcmp(theName, "LuckySpin") == 0)
		return ExtractLuckySpinResources(theManager);
	if (strcmp(theName, "MainMenu") == 0)
		return ExtractMainMenuResources(theManager);
	if (strcmp(theName, "Story") == 0)
		return ExtractStoryResources(theManager);
	if (strcmp(theName, "Upsell") == 0)
		return ExtractUpsellResources(theManager);
	return false;
}

